171 :         config, errorReporter);
172 :     Node irNode = irFactory.transform(node);
173 : 
174 :     if (node.getComments() != null) {
175 :       for (Comment comment : node.getComments()) {
176 :         if (comment.getCommentType() == CommentType.JSDOC &&
177 :             !irFactory.parsedComments.contains(comment)) {
178 :           irFactory.handlePossibleFileOverviewJsDoc(comment, irNode);
179 :         } else if (comment.getCommentType() == CommentType.BLOCK_COMMENT) {
180 :           irFactory.handleBlockComment(comment);
181 :         }
182 :       }
183 :     }
184 : 
185 :     irFactory.setFileOverviewJsDoc(irNode);
186 : 
187 :     return irNode;
188 :   }"

